#!/bin/sh
# vibTTY / Ghostty  kitty 图形协议对齐诊断
#
# 每段画一个 4 列 × 2 行的方块，右边两行文字标出方块上下边应在的位置。
# 方块正好卡在两行之间的那一段，就是这个终端能正确处理的形式。
#
#   A  原样      ratatui-image 目前发出的字节：虚拟放置不带 c/r，
#                每行以 CSI s 开头、CSI u + 相对移动收尾
#   B  补 c/r    传输里显式给出占位的列数行数，终端不必自己推算
#   C  去收尾    不用 CSI s / CSI u，改用绝对列定位
#
# A 歪 B 齐  → 终端推算行数的方式和别人不同，ratatui-image 该补 c/r
# A 歪 C 齐  → 终端没有实现 CSI s / CSI u（SCOSC/SCORC）
# 都歪       → 虚拟放置本身的实现有出入
#
# 用法：sh kitty-alignment.sh

printf "终端: ${TERM_PROGRAM:-?} ${TERM_PROGRAM_VERSION:-?}  TERM=${TERM:-?}\n\n"

printf "A  原样（ratatui-image 现在发的）\n"
printf '\033_Gq=2,i=11189196,a=T,U=1,f=32,t=d,s=64,v=70,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=0;\033\\'
printf '\033[s\033[38;2;170;187;204m􎻮̅̅̅􎻮􎻮􎻮\033[u\033[3C\033[1B'
printf '  ← 上边应与本行齐平\n'
printf '\033[s\033[38;2;170;187;204m􎻮̍̅̅􎻮􎻮􎻮\033[u\033[3C\033[1B'
printf '  ← 下边应与本行齐平\n'
printf "\n"
printf "B  传输里补上 c=4,r=2\n"
printf '\033_Gq=2,i=11189196,a=T,U=1,f=32,t=d,s=64,v=70,c=4,r=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=0;\033\\'
printf '\033[s\033[38;2;170;187;204m􎻮̅̅̅􎻮􎻮􎻮\033[u\033[3C\033[1B'
printf '  ← 上边应与本行齐平\n'
printf '\033[s\033[38;2;170;187;204m􎻮̍̅̅􎻮􎻮􎻮\033[u\033[3C\033[1B'
printf '  ← 下边应与本行齐平\n'
printf "\n"
printf "C  收尾改绝对列定位，不用 CSI s/u\n"
printf '\033_Gq=2,i=11189196,a=T,U=1,f=32,t=d,s=64,v=70,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=0;\033\\'
printf '\r\033[38;2;170;187;204m􎻮̅̅̅􎻮􎻮􎻮\033[0m\033[7G← 上边应与本行齐平\n'
printf '\r\033[38;2;170;187;204m􎻮̍̅̅􎻮􎻮􎻮\033[0m\033[7G← 下边应与本行齐平\n'
printf "\n"
printf "哪一段是齐的，就说明这个终端认哪种形式。\n"
